use super::*;
use crate::money::{money, Money};

/// What you may short, and the price at which it ends.
///
/// The call price solves `equity + shares·entry = shares·price·(1 + maintenance)` — the point where
/// account equity falls to the maintenance requirement. Below the maximum position the headroom is
/// larger; at the maximum it is about 15%, which is less than a bad week.
pub fn capacity(equity: Money, price: Money, shares: Option<i64>, rules: &MarginRules) -> Result<Capacity, String> {
    if equity.minor <= 0 {
        return Err("no equity, so no position — a short is collateral before it is a trade".to_string());
    }
    if price.minor <= 0 {
        return Err("a price of zero or less is not a price".to_string());
    }
    if equity.currency != price.currency {
        return Err(format!("equity is in {} and the price is in {}", equity.currency, price.currency));
    }
    if rules.initial <= 0.0 || rules.initial > 1.0 {
        return Err(format!("an initial margin of {} is not a fraction between 0 and 1", rules.initial));
    }
    if rules.maintenance <= 0.0 || rules.maintenance >= 1.0 {
        return Err(format!("a maintenance margin of {} is not a fraction between 0 and 1", rules.maintenance));
    }

    let cur = equity.currency;
    let max_position_minor = (equity.minor as f64 / rules.initial).floor() as i64;
    let max_shares = max_position_minor / price.minor.max(1);
    let n = shares.unwrap_or(max_shares);
    let mut notes: Vec<String> = Vec::new();

    if n <= 0 {
        return Err(format!(
            "{} of equity does not reach one share at {} — Regulation T needs {} of your own money per {} shorted",
            crate::money::format_minor(equity.minor),
            crate::money::format_minor(price.minor),
            crate::money::format_minor((price.minor as f64 * rules.initial).ceil() as i64),
            crate::money::format_minor(price.minor)
        ));
    }
    if n > max_shares {
        notes.push(format!(
            "{n} shares exceeds the {max_shares} Regulation T allows on this equity — the figures below are for a position you could not open"
        ));
    }
    // A US margin account needs $2,000 of equity before it may short at all, whatever the
    // arithmetic above says. Stated rather than silently assumed away.
    if equity.minor < 200_000 {
        notes.push("a US margin account requires $2,000 of equity before it may short at all, regardless of position size".to_string());
    }

    let call = (equity.minor as f64 + (n * price.minor) as f64) / (n as f64 * (1.0 + rules.maintenance));
    let call_minor = call.floor() as i64;
    let headroom = (call_minor as f64 - price.minor as f64) / price.minor as f64;

    Ok(Capacity {
        equity,
        price,
        max_position: money(max_position_minor, cur),
        max_shares,
        margin_call_price: money(call_minor, cur),
        headroom,
        notes,
    })
}
